import {nextLearnerAction,pendingPlanView} from '../learner-state.mjs';
import {esc,money,today,date,intro,empty,stat,progress,progressBar,bookingsView} from '../presentation.mjs';
export function learnerOverview({state,course,metrics}) {
 const en=state.active_enrollment, action=nextLearnerAction(state), p=progress(course),next=state.bookings.filter(b=>b.status==='confirmed'&&new Date(b.starts_at)>new Date()).sort((a,b)=>a.starts_at.localeCompare(b.starts_at))[0];
 return `${intro('Welcome, '+state.me.name,'Every lesson brings you closer to confident driving.')}<div class="stats">${stat('Lessons left',en?.credits_remaining||0)}${stat('Reserved lessons',metrics.confirmed_count||0)}${stat('Completed lessons',metrics.completed_count||0)}${stat('Learning progress',p.total+'%')}</div><div class="grid section-gap"><section class="panel panel-pad lesson-hero"><div class="eyebrow">NEXT LESSON</div>${next?`<h2>${date(next.date)} · ${esc(next.time)} IST</h2><p>${esc(next.instructor_name)} · ${esc(next.vehicle_name)}</p>`:`<h2>Your next step starts here.</h2><p>${esc(action.description)}</p>`}<button class="primary lime section-gap" data-nav="${action.page}">${action.label} →</button></section><section class="panel panel-pad"><h2>Your learning journey</h2>${progressBar('Theory',p.theory)}${progressBar('Practical',p.practical)}<button class="link" data-nav="syllabus">Explore your syllabus →</button></section></div>${pendingPlanView(state)}${en?.review_required?'<p class="banner-alert">Your previous plan activation needs receipt review. Contact the school before booking.</p>':''}<section class="section-gap"><h2>Recent lessons</h2>${bookingsView(state.bookings.slice(0,3),'student')}</section>`;
}
export function plansView({state}) {
 const en=state.active_enrollment;
 return `${intro('A plan for your journey','One credit is used when your instructor completes a lesson.')}${pendingPlanView(state)} ${en?`<section class="plan-active-badge"><h2>${esc(en.plan_name)}</h2><p>${en.credits_remaining} lessons left · ${en.credits_reserved} reserved · ${esc(en.instructor_name)}</p></section>`:''}<div class="plan-cards-grid section-gap">${state.plans.map((p,i)=>`<section class="plan-card ${i===1?'highlight':''}"><div class="eyebrow">${p.lesson_credits} GUIDED LESSONS</div><h2>${esc(p.name)}</h2><div class="price"><b>${money(p.price_inr)}</b></div><ul class="plan-features"><li>${p.lesson_credits} practical lesson credits</li><li>One hour of guided practice per lesson</li><li>Theory resources and progress tracking</li><li>Your chosen school instructor</li></ul><button class="primary full" data-enroll="${esc(p.id)}" ${en||state.pending_enrollment||!state.instructors.length?'disabled':''}>Choose plan</button></section>`).join('')}</div>${!state.instructors.length?'<p class="hint">No approved instructors yet. Contact the school before purchasing.</p>':''}`;
}
export function bookView({state,draft,times,slotError,loadingSlots,busy}) {
 const en=state.active_enrollment;
 if(state.pending_enrollment)return intro('Book a lesson','Finish your existing plan purchase first.')+pendingPlanView(state);
 if(en?.review_required)return intro('Payment review required','Contact the school before reserving another lesson.')+'<button class="secondary" data-nav="payments">View payment status</button>';
 if(en&&Number(en.credits_remaining)<=Number(en.credits_reserved))return intro('All remaining credits are reserved','Complete a lesson, or cancel a future lesson to free its reserved credit.')+'<button class="secondary" data-nav="lessons">View my lessons</button>';
 if(!en)return intro('Book a lesson','Choose a plan to begin.')+empty('Buy a plan to book','Your plan must be paid before booking.')+'<button class="primary" data-nav="plans">View plans</button>';
 const vehicles=state.vehicles.filter(v=>v.active);
 return `${intro('Book a lesson',`${en.credits_remaining} lessons left · ${en.credits_reserved} already reserved · ${en.instructor_name}`)}<div class="grid"><section class="panel panel-pad booking-form"><label>Lesson date<input id="lesson-date" type="date" min="${today()}" value="${esc(draft.date)}" required></label><label>Training vehicle<select id="vehicle">${vehicles.map(v=>`<option value="${esc(v.id)}" ${v.id===draft.vehicle?'selected':''}>${esc(v.name)} · ${esc(v.transmission)}</option>`).join('')}</select></label><h2>One-hour slots · IST</h2>${!vehicles.length?empty('No active training vehicles','Contact the school to arrange a vehicle.'):loadingSlots?'<p role="status">Loading availability…</p>':slotError?`<p class="error" role="alert">${esc(slotError)}</p><button class="secondary" id="slots-retry">Retry availability</button>`:`<div class="slots">${!times.length?empty('No teaching hours on this date','Choose another day or contact the school.'):''}${times.map(t=>`<button class="slot ${draft.time===t.time?'selected':''}" data-time="${esc(t.time)}" aria-pressed="${draft.time===t.time}" ${t.available?'':'disabled'}>${esc(t.time)}</button>`).join('')}</div>`}</section><section class="panel panel-pad"><h2>Your lesson</h2><p class="summary-line">${date(draft.date)} · ${esc(draft.time||'Choose a time')}</p><p class="sub">Credits are used after completion. You can cancel before the lesson starts.</p><button class="primary full section-gap" id="reserve" ${draft.time&&!loadingSlots&&!busy?'':'disabled'}>Reserve lesson</button></section></div>`;
}
